function CastingBreakoutChiselMaker.init() CastingBreakoutChiselMaker.ironStock=18; CastingBreakoutChiselMaker.bronzeStock=14; CastingBreakoutChiselMaker.woodStock=10; CastingBreakoutChiselMaker.leatherStock=8; CastingBreakoutChiselMaker.silverStock=8; CastingBreakoutChiselMaker.goldStock=6; CastingBreakoutChiselMaker.jewelStock=4; CastingBreakoutChiselMaker.pearlStock=4; CastingBreakoutChiselMaker.productStock={}; CastingBreakoutChiselMaker.buildings={}; CastingBreakoutChiselMaker.maker=nil; CastingBreakoutChiselMaker.activeMaking={}; CastingBreakoutChiselMaker.totalProducts=0; CastingBreakoutChiselMaker.dayTimer=0; print("[CastingBreakoutChiselMaker] Royal Casting Breakout Chisel Maker System initialized (6 products, 4 buildings)") end
function CastingBreakoutChiselMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CastingBreakoutChiselMaker.maker={name=n or ("Dletnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dletnik najet: %s (spretnost: %d)",CastingBreakoutChiselMaker.maker.name,s),"success") end; return true end
function CastingBreakoutChiselMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CastingBreakoutChiselMaker.build(id) local ok,e=CastingBreakoutChiselMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CastingBreakoutChiselMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CastingBreakoutChiselMaker.getQualityBonus() local b=0; for _,bd in ipairs(CastingBreakoutChiselMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CastingBreakoutChiselMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CastingBreakoutChiselMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CastingBreakoutChiselMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CastingBreakoutChiselMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CastingBreakoutChiselMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CastingBreakoutChiselMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CastingBreakoutChiselMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CastingBreakoutChiselMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CastingBreakoutChiselMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CastingBreakoutChiselMaker.buildings==0 then return false,"Potrebna dletna delavnica" end; if not CastingBreakoutChiselMaker.maker then return false,"Potreben dletnik" end; return true end
function CastingBreakoutChiselMaker.make(pt,qty) qty=qty or 1; local ok,e=CastingBreakoutChiselMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CastingBreakoutChiselMaker.ironStock=CastingBreakoutChiselMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CastingBreakoutChiselMaker.bronzeStock=CastingBreakoutChiselMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CastingBreakoutChiselMaker.woodStock=CastingBreakoutChiselMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CastingBreakoutChiselMaker.leatherStock=CastingBreakoutChiselMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CastingBreakoutChiselMaker.silverStock=CastingBreakoutChiselMaker.silverStock-d.silverCost*qty end; if d.goldCost then CastingBreakoutChiselMaker.goldStock=CastingBreakoutChiselMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CastingBreakoutChiselMaker.jewelStock=CastingBreakoutChiselMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CastingBreakoutChiselMaker.pearlStock=CastingBreakoutChiselMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CastingBreakoutChiselMaker.maker then t=math.max(1,t-math.floor(CastingBreakoutChiselMaker.maker.skill/13)) end; table.insert(CastingBreakoutChiselMaker.activeMaking,{id="castingbreakoutchisel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CastingBreakoutChiselMaker.completeMaking(m) local q=1.0+(CastingBreakoutChiselMaker.getQualityBonus()/100); if CastingBreakoutChiselMaker.maker then q=q+(CastingBreakoutChiselMaker.maker.skill/140) end; q=math.min(2.5,q); CastingBreakoutChiselMaker.productStock[m.productType]=(CastingBreakoutChiselMaker.productStock[m.productType] or 0)+m.quantity; CastingBreakoutChiselMaker.totalProducts=CastingBreakoutChiselMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CastingBreakoutChiselMaker.maker then CastingBreakoutChiselMaker.maker.itemsMade=CastingBreakoutChiselMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CastingBreakoutChiselMaker.maker.skill=math.min(100,CastingBreakoutChiselMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dleto izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"castingbreakoutchisel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CastingBreakoutChiselMaker.update(dt) if not _G.state then return end; CastingBreakoutChiselMaker.dayTimer=CastingBreakoutChiselMaker.dayTimer+dt; if CastingBreakoutChiselMaker.dayTimer>=30 then CastingBreakoutChiselMaker.dayTimer=0; for i=#CastingBreakoutChiselMaker.activeMaking,1,-1 do local m=CastingBreakoutChiselMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CastingBreakoutChiselMaker.completeMaking(m); table.remove(CastingBreakoutChiselMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CastingBreakoutChiselMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CastingBreakoutChiselMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CastingBreakoutChiselMaker.getStats() return {ironStock=CastingBreakoutChiselMaker.ironStock,bronzeStock=CastingBreakoutChiselMaker.bronzeStock,woodStock=CastingBreakoutChiselMaker.woodStock,leatherStock=CastingBreakoutChiselMaker.leatherStock,silverStock=CastingBreakoutChiselMaker.silverStock,goldStock=CastingBreakoutChiselMaker.goldStock,jewelStock=CastingBreakoutChiselMaker.jewelStock,pearlStock=CastingBreakoutChiselMaker.pearlStock,productStock=CastingBreakoutChiselMaker.productStock,numBuildings=#CastingBreakoutChiselMaker.buildings,hasMaker=CastingBreakoutChiselMaker.maker~=nil,makerName=CastingBreakoutChiselMaker.maker and CastingBreakoutChiselMaker.maker.name or "—",makerSkill=CastingBreakoutChiselMaker.maker and CastingBreakoutChiselMaker.maker.skill or 0,activeMaking=#CastingBreakoutChiselMaker.activeMaking,totalProducts=CastingBreakoutChiselMaker.totalProducts} end
